"""Derive timings from original compact receipts only; never benchmark/transfer."""
import hashlib,json,re,statistics
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];STORAGE=ROOT/'research/onchain-paper-replication-2026-09-24/storage';RATE=262144*1024//8
pins={}
def read(p):
 assert p.suffix=='.json' and p.stat().st_size<4*1024**2 and 'connection' not in p.name
 raw=p.read_bytes();pins[str(p.relative_to(ROOT))]=hashlib.sha256(raw).hexdigest();return json.loads(raw)
def mtime(p):return p.stat().st_mtime_ns/1e9
def psi(text):
 return {line.split()[0]:int(re.search(r'total=(\d+)',line).group(1)) for line in text.splitlines()}
cases=[]
for label,name,expected_n in [('May2','real-pilot-first-graph-preservation-20261006-01',73),('May9','real-pilot-second-graph-preservation-20261006-01',71)]:
 p=STORAGE/name;selection=read(p/'selection01.json');g=read(p/'guard01/final.json');all_gets=[read(q) for q in sorted(p.glob('*.transport.json'))];assert len(all_gets)==expected_n
 assert all(x['status']=='complete' and x['returncode']==0 and x['expected_bytes']==x['received_bytes'] for x in all_gets)
 rows=[]
 for i,r in enumerate(selection['files']):
  if r['bytes']<=4*1024**2:continue
  receipt=p/f'{i:02d}-recovered.bin.transport.json';v=read(receipt);attempt=p/f'{i:02d}-attempted.json';kept=p/f'{i:02d}-kept.json'
  match=re.search(r'(\d+) bytes .* copied, ([0-9.]+) s,',v['stderr_tail']);assert match and int(match[1])==r['bytes'];dd=float(match[2])
  get_s=v['elapsed_seconds'];until_get=mtime(receipt)-mtime(attempt);row_s=mtime(kept)-mtime(attempt)
  rows.append({'row':i,'body':Path(r['path']).name,'bytes':r['bytes'],'get_elapsed_seconds':get_s,'get_MiB_per_second':r['bytes']/1024**2/get_s,'get_fraction_of_selected_rate':r['bytes']/get_s/RATE,'remote_dd_reported_seconds':dd,'get_minus_remote_dd_seconds':get_s-dd,'attempt_to_kept_receipt_mtime_seconds':row_s,'pre_get_interval_minus_get_seconds':until_get-get_s,'post_get_receipt_to_kept_seconds':mtime(kept)-mtime(receipt),'get_receipt':str(receipt.relative_to(ROOT)),'get_receipt_sha256':pins[str(receipt.relative_to(ROOT))]})
 assert len(rows)==6
 small=[x for x in all_gets if x['expected_bytes']<=4*1024**2];sum_get=sum(x['elapsed_seconds'] for x in all_gets);unit=g['optional_memory_telemetry']['unit']
 cases.append({'graph':label,'identity':name,'original_phase':g['phase'],'original_guard_child_exit_code':g['child_exit_code'],'original_limit_reason':g['limit_reason'],'native_elapsed_seconds':g['elapsed_seconds'],'six_payloads':rows,'six_payload_bytes':sum(r['bytes'] for r in rows),'six_payload_get_seconds':sum(r['get_elapsed_seconds'] for r in rows),'six_payload_attempt_to_kept_mtime_seconds':sum(r['attempt_to_kept_receipt_mtime_seconds'] for r in rows),'get_receipts':len(all_gets),'all_get_received_bytes':sum(x['received_bytes'] for x in all_gets),'all_get_elapsed_seconds':sum_get,'native_minus_summed_get_seconds':g['elapsed_seconds']-sum_get,'small_get_count':len(small),'small_get_bytes':sum(x['received_bytes'] for x in small),'small_get_elapsed_seconds':sum(x['elapsed_seconds'] for x in small),'small_get_median_seconds':statistics.median(x['elapsed_seconds'] for x in small),'small_get_min_seconds':min(x['elapsed_seconds'] for x in small),'small_get_max_seconds':max(x['elapsed_seconds'] for x in small),'small_get_share_of_native_elapsed':sum(x['elapsed_seconds'] for x in small)/g['elapsed_seconds'],'memory':{'high_bytes':g['memory_high_bytes'],'max_bytes':g['memory_max_bytes'],'high_events_delta':g['memory_events']['high']-g['initial_memory_events']['high'],'max_events':g['memory_events']['max'],'oom_events':g['memory_events']['oom'],'last_unit_kernel_peak_bytes':unit['kernel_peak_bytes'],'sampled_peak_bytes':g['peak_sampled_memory_current_bytes'],'last_unit_file_bytes':unit['file_bytes'],'last_unit_anon_bytes':unit['anon_bytes'],'last_unit_psi_total_microseconds':psi(unit['pressure']),'terminal_snapshot_present':g.get('terminal_memory_snapshot') is not None,'qualification':'Unit counters only; file/cache is included in charged memory, not RSS. Last readings need not be final lifetime values after abrupt termination. Ancestor is excluded.'}})
source_names=[STORAGE/'real-pilot-first-graph-preservation-20261006-01/entry03.py',STORAGE/'real-pilot-second-graph-preservation-20261006-01/entry01.py',STORAGE/'closed-ledger-pilot-offload-2026-10-05-01/transport.py',STORAGE/'raw-preservation-2026-09-28-09/transfer.py',ROOT/'research/onchain-paper-replication-2026-09-24/full_sources/real-data-pilot-second-graph-preservation-preparation01-2026-10-06/keep.py']
source_pins={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in source_names}
record={'scope':'Two original ordinary backups only; May2 COMPLETE, May9 permanently FAILED. No rerun or payload read.','selected_rate_bytes_per_second':RATE,'selected_rate_MiB_per_second':32,'cases':cases,'timing_semantics':{'get':'Actual monotonic receive receipt elapsed includes subprocess startup, stream receive/rate wait, output fsync and child teardown.','remote_dd':'Original stderr reported remote command duration; includes output backpressure and is not isolated network wire time.','get_minus_remote_dd':'Mixed startup/teardown/fsync timing difference with rounded remote counter; not isolated SSH startup.','receipt_mtime_intervals':'Wall-clock metadata receipt differences, not instrumented phase timers; clock/mtime resolution applies.','pre_get_interval_minus_get':'Contains original source validation/hash/open plus SCP upload and bookkeeping. No separate upload timer exists.','native_minus_get':'Mixed upload, local hash checks, metadata/control commands, startup/guard and cleanup; not all subprocess overhead.'},'source_observations':{'put':'SCP -l262144 selected; no success elapsed receipt in Transport.run/put.','get':'32MiB/s receive upper cap; new SSH process per get, remote dd32768B blocks.','hashing':'keep_one validates/hashes original three times and hashes recovered body once; per-hash durations not retained.','memory':'High-event crossings and cache charging observed; PSI last totals small relative to elapsed, but no before/after cap comparison or high-throttle duration decomposition. No causal speedup established.'},'practical_decision':'Measured bulk body path dominates. Do not increase the already32MiB/s rate cap or memory envelope based on these receipts. Metadata get batching addresses only about1.4–1.7% measured native time before unmeasured put savings. Exact unresolved question is time split between SCP upload, local validation reads, network/remote output and receiver work; add bounded per-put/per-validation elapsed receipts to a future separately reviewed ordinary source if attribution is needed, without retransferring historical jobs.','source_pins':source_pins,'compact_receipt_count_hashed':len(pins),'compact_receipt_pins':pins}
(HERE/'TIMING01.json').write_text(json.dumps(record,sort_keys=True,indent=2)+'\n')
print(json.dumps({'cases':[{'graph':c['graph'],'native_s':c['native_elapsed_seconds'],'ledger_get_s':c['six_payloads'][0]['get_elapsed_seconds'],'ledger_get_MiB_s':c['six_payloads'][0]['get_MiB_per_second'],'small_get_s':c['small_get_elapsed_seconds'],'all_get_s':c['all_get_elapsed_seconds'],'high_events':c['memory']['high_events_delta'],'last_PSI_us':c['memory']['last_unit_psi_total_microseconds']} for c in cases]},indent=2))
